def get_summary(data):
    summary = {'avg': 0, 'max': 0, 'min': 0, 'total': 0}

    for num in data['nums']:
        summary['total'] += num
        if num > summary['max']:
            summary['max'] = num
        if num < summary['min']:
            summary['min'] = num

    avg = summary['total'] / len(data['nums'])
    summary['avg'] = avg

    return summary

