def convert_to_bytes(data):
    return data.encode('utf-8')

def create_message(user, message):
    msg = f'<b>{user}</b>: {message}'

    html_safe = escape(msg)
    bytes_msg = convert_to_bytes(html_safe)
    base64_msg = base64.b64encode(bytes_msg)
    encrypted_msg = encrypt(base64_msg)

    return encrypted_msg

