import random

def circus_act(animals):
    print("Welcome to the circus! Let's see some animal tricks!")
    for animal in animals:
        trick = random.choice(['jump', 'spin', 'crawl'])
        print(f"{animal} is going to {trick}!")

        trick_performed = random.choice([True, False])
        if trick_performed:
            print(f"{animal} did {trick}!")
        else:
            print(f"{animal} was too scared and didn't {trick}...")
        print()

    print("Thank you for coming to the circus!")

if __name__ == "__main__":
    animals = ['lions', 'tigers', 'bears']
    circus_act(animals)

