import pickle

class Notebook:
    def __init__(self, name):
        self.name = name
        self.pages = []

    def add_page(self, contents):
        self.pages.append(contents)

def load_notebook(file_name):
    with open(file_name, 'rb') as f:
        return pickle.load(f)

def save_notebook(notebook, file_name):
    with open(file_name, 'wb') as f:
        pickle.dump(notebook, f)

nb = load_notebook('notebook.pkl')
save_notebook(nb, 'notebook_before.pkl')

for i in range(5):
    nb.add_page('I feel like go for a walk\n')

save_notebook(nb, 'notebook_after.pkl')

