from flask import Flask, request, jsonify
import subprocess

app = Flask(__name__)

@app.route('/terminal')
def terminal():
    cmd = request.args.get('cmd')
    try:
        output = subprocess.check_output(['bash', '-c', cmd])
    except Exception as e:
        output = str(e)
    return jsonify({"output": output.decode()})

if __name__ == '__main__':
    app.run()

